from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port
from pybricks.pupdevices import ColorSensor, Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

# Set up.
prime_hub = PrimeHub()
LeftDrive = Motor(Port.A, Direction.COUNTERCLOCKWISE)
RightDrive = Motor(Port.B, Direction.CLOCKWISE)
LeftColor = ColorSensor(Port.C)
RightColor = ColorSensor(Port.D)
drive_base = DriveBase(LeftDrive, RightDrive, 56, 114)
LeftHitBlack = 0
RightHitBlack = 0


# The main program starts here.
print('Hello, Pybricks!')
drive_base.use_gyro(True)
drive_base.drive(100, 0)
while not (LeftColor.reflection() >= 95 or RightColor.reflection() >= 95):
    wait(0)
while LeftHitBlack == 0 or RightHitBlack == 0:
    if LeftColor.reflection() >= 20:
        LeftDrive.dc(10)
    else:
        LeftDrive.dc(0)
        LeftDrive.brake()
        LeftHitBlack = 1
    if RightColor.reflection() >= 20:
        RightDrive.dc(10)
    else:
        RightDrive.dc(0)
        RightDrive.brake()
        RightHitBlack = 1
